            if (country === 'US') {
                for (let i = 0; i < 2; i++) {
                    (monthSections[i]).style['order'] = '0';
                    (firstDelimiters[i]).style['order'] = '1';
                    (daySections[i]).style['order'] = '2';
                    (secondDelimiters[i]).style['order'] = '3';
                    (yearSections[i]).style['order'] = '4';
