                    (monthSections[i]).style['order'] = '1';
                    (firstDelimiters[i]).style['order'] = '2';
                    (daySections[i]).style['order'] = '3';
                }
            } else {
                for (let i = 0; i < 2; i++) {
                    (daySections[i]).style['order'] = '-1';
                    (firstDelimiters[i]).style['order'] = '0';
                    (monthSections[i]).style['order'] = '1';
