        function isValidUrl(url) {
            if (!url) {
                return false;
            }
            var encodedUrl = encodeURI(url);
            return encodedUrl.match(
                /^(https?:\/\/)?(([a-z0-9-]|%[A-F0-9]{2})+\.)+(([a-z]|%[A-F0-9]{2})([a-z0-9]|%[A-F0-9]{2})*)(:[0-9]+)?(\/[a-z0-9;:,~!+#@&=%\/$\.?_-]+)?$/i
